import pandas as pd
import re
import random

def task_func(s: str, seed: int = 0) -> pd.DataFrame:
    rng = random.Random(seed)
    products_list = ['Apple', 'Banana', 'Orange', 'Pear', 'Grape']

    rows = []
    for line in s.splitlines():
        if not line.strip():
            continue

        parts = line.split(maxsplit=4)
        if len(parts) != 5:
            continue

        id_val = parts[0].rstrip()
        qty_val = int(parts[1].rstrip())
        code_val = parts[2].rstrip()
        price_val = int(parts[3].rstrip())
        desc_val = parts[4].rstrip()

        rows.append([id_val, qty_val, code_val, price_val, desc_val])

    df = pd.DataFrame(
        rows,
        columns=['ID', 'Quantity', 'Code', 'Price', 'Description']
    )

    if df.empty:
        return pd.DataFrame(columns=['ID', 'Quantity', 'Code', 'Price', 'Product', 'Description']).astype({
            'Quantity': 'int64',
            'Price': 'int64'
        })

    code_to_product = {
        code: rng.choice(products_list)
        for code in df['Code'].unique()
    }

    df['Product'] = df['Code'].map(code_to_product)
    return df[['ID', 'Quantity', 'Code', 'Price', 'Product', 'Description']]
